"""
Stage 6: Structured Radiology Report Generator
- Assembles all pipeline outputs into a complete structured report dict
- Follows standard radiology report template
- MANDATORY DISCLAIMER always included — AI-assisted decision-support only
"""

import datetime
import uuid


AI_DISCLAIMER = (
    "⚠ AI-ASSISTED PRELIMINARY ANALYSIS — FOR RESEARCH/DECISION-SUPPORT ONLY. "
    "This report was generated by an automated AI system and has NOT been reviewed "
    "by a licensed radiologist or physician. All findings, measurements, and risk "
    "assessments MUST be confirmed by a qualified medical professional before any "
    "clinical decision is made. This system is NOT FDA/CE approved for clinical use. "
    "WHO Grade (I-IV) and malignancy type CANNOT be determined by AI imaging alone — "
    "histopathological confirmation (biopsy) is required."
)


def generate_structured_report(
    patient_meta,
    scan_meta,
    detection_result,
    mask_stats,
    measurements,
    growth_data,
    radiomics,
    risk_data,
    grade_label,
    confidence,
    overlay_b64="",
    original_img_b64="",
    insufficient_mask_data=False,
    uncertainty_score=None,
    mass_effect=None,
):
    """
    Assemble the complete structured radiology report.
    """
    report_id = str(uuid.uuid4())
    timestamp = datetime.datetime.now().isoformat()
    
    # Calculate pipeline stage status
    preprocessing_status = "fail" if scan_meta.get('warning') and "failed" in str(scan_meta.get('warning')).lower() else "pass"
    
    is_tumor = detection_result.get('is_tumor', False)
    if not is_tumor:
        segmentation_status = "skipped"
        radiomics_status = "skipped"
        risk_scoring_status = "skipped"
        grading_status = "skipped"
    elif insufficient_mask_data:
        segmentation_status = "fail"
        radiomics_status = "skipped"
        risk_scoring_status = "skipped"
        grading_status = "skipped"
    else:
        segmentation_status = "pass"
        radiomics_status = "pass" if radiomics else "fail"
        risk_scoring_status = "pass" if risk_data else "fail"
        grading_status = "pass" if grade_label and grade_label != "—" and grade_label != "N/A" else "fail"
        
    uncertainty_status = "pass" if uncertainty_score is not None else "skipped"
    mass_effect_status = "pass" if mass_effect is not None else "skipped"

    pipeline_stages = {
        'preprocessing':  preprocessing_status,
        'segmentation':   segmentation_status,
        'radiomics':      radiomics_status,
        'risk_scoring':   risk_scoring_status,
        'grading':        grading_status,
        'uncertainty':    uncertainty_status,
        'mass_effect':    mass_effect_status,
    }
    
    # ── Section 1: Header ──
    header = {
        'report_id': report_id,
        'timestamp': timestamp,
        'date_formatted': datetime.datetime.now().strftime('%Y-%m-%d %H:%M'),
        'report_version': '2.0',
        'model_version': '2.0',
        'ai_system': 'NeuroScan AI — Hybrid CNN-Transformer v2.0',
        'report_type': 'AI-Assisted MRI Brain Tumor Analysis',
        'pipeline_stages': pipeline_stages
    }

    # ── Section 2: Patient Information ──
    patient = {
        'name': patient_meta.get('name', 'Anonymous'),
        'case_id': patient_meta.get('case_id', f'CASE-{report_id[:8].upper()}'),
        'age': patient_meta.get('age', 'N/A'),
        'sex': patient_meta.get('sex', 'N/A'),
        'referring_physician': patient_meta.get('physician', 'N/A'),
    }

    # ── Section 3: Scan Metadata ──
    scan = {
        'modality': 'MRI',
        'sequences_analyzed': 'T1 / T1CE / T2 / FLAIR (simulated multi-channel)',
        'pixel_spacing_x_mm': scan_meta.get('pixel_spacing_x', 1.0),
        'pixel_spacing_y_mm': scan_meta.get('pixel_spacing_y', 1.0),
        'slice_thickness_mm': scan_meta.get('slice_thickness', 5.0),
        'voxel_volume_mm3': scan_meta.get('voxel_volume_mm3', 5.0),
        'image_shape': scan_meta.get('image_shape', {}),
        'orientation': scan_meta.get('orientation', 'AXIAL'),
        'scan_source': scan_meta.get('source', 'unknown'),
        'metadata_warning': scan_meta.get('warning'),
    }

    # ── Section 4: Detection Result ──
    detection = {
        'finding': 'POSITIVE — Space-Occupying Lesion (SOL) Identified' if is_tumor
                   else 'NEGATIVE — No Radiological Anomaly Detected',
        'is_tumor': is_tumor,
        'ai_confidence': round(confidence * 100, 1),
        'grade_indicator': grade_label,
        'segmentation_threshold_used': detection_result.get('threshold', 0.5),
        'detection_method': detection_result.get('method', 'Hybrid CNN-Transformer + Heuristic'),
    }

    # ── Section 5: Quantitative Measurements ──
    vol_ml = measurements.get('volume_ml', 0.0)
    diam_mm = measurements.get('diameter_mm', 0.0)
    perp_mm = measurements.get('perpendicular_mm', 0.0)

    meas = {
        'volume_ml': vol_ml,
        'volume_cm3': vol_ml,  # mL == cm³
        'longest_diameter_mm': diam_mm,
        'perpendicular_diameter_mm': perp_mm,
        'rano_criteria': f'{diam_mm:.1f} × {perp_mm:.1f} mm (longest × perpendicular)' if not insufficient_mask_data else '—',
        'voxel_count': measurements.get('voxel_count', 0),
        'bounding_box': measurements.get('bounding_box', {}),
        'growth_tracking': growth_data,
    }

    # ── Section 6: Radiomics Summary ──
    rad_shape = radiomics.get('shape', {}) if radiomics else {}
    rad_enh = radiomics.get('enhancement', {}) if radiomics else {}
    rad_edema = radiomics.get('edema', {}) if radiomics else {}
    rad_loc = radiomics.get('location', {}) if radiomics else {}
    rad_tex = radiomics.get('texture', {}) if radiomics else {}

    radiomics_summary = {
        'anatomical_location': rad_loc.get('full_location', 'N/A'),
        'laterality': rad_loc.get('laterality', 'N/A'),
        'depth_category': rad_loc.get('depth_category', 'N/A'),
        'is_eloquent_area': rad_loc.get('is_eloquent', False),
        'surgical_risk_flag': rad_loc.get('surgical_risk', 'Unknown'),
        'enhancement_pattern': rad_enh.get('enhancement_pattern', 'N/A'),
        'enhancement_ratio': rad_enh.get('enhancement_ratio', 0.0),
        'ring_enhancement': rad_enh.get('is_ring_enhancement', False),
        'edema_label': rad_edema.get('edema_label', 'N/A'),
        'edema_ratio': rad_edema.get('edema_ratio', 0.0),
        'shape_label': rad_shape.get('shape_label', 'N/A'),
        'sphericity': rad_shape.get('sphericity', 0.0),
        'irregularity': rad_shape.get('irregularity', 0.0),
        'texture_label': rad_tex.get('texture_label', 'N/A'),
        'texture_homogeneity': rad_tex.get('homogeneity', 0.0),
        'texture_entropy': rad_tex.get('entropy', 0.0),
    }

    # ── Section 7: Risk Assessment ──
    risk = {
        'composite_score': risk_data.get('total_score', 0) if risk_data else 0,
        'risk_level': risk_data.get('risk_level', 'N/A') if risk_data else 'N/A',
        'risk_color': risk_data.get('risk_color', '#888') if risk_data else '#888',
        'factor_breakdown': risk_data.get('factor_breakdown', []) if risk_data else [],
        'clinical_note': risk_data.get('clinical_note', '') if risk_data else '',
        'confidence_adjusted_score': risk_data.get('confidence_adjusted_score', 0) if risk_data else 0,
    }

    # ── Section 8: AI-Generated Clinical Impression ──
    impression = (
        _generate_impression(is_tumor, meas, radiomics_summary, risk, grade_label,
                             uncertainty_score=uncertainty_score, mass_effect=mass_effect)
        if not insufficient_mask_data
        else "Analysis Incomplete — Manual Review Required"
    )

    # ── Section 9: Uncertainty (MC-Dropout) ──
    uncertainty = None
    if uncertainty_score is not None:
        conf_level = (
            "High Confidence"   if uncertainty_score < 0.02 else
            "Moderate Confidence" if uncertainty_score < 0.06 else
            "Low Confidence — Manual Review Recommended"
        )
        uncertainty = {
            "score":         round(float(uncertainty_score), 5),
            "confidence_level": conf_level,
            "mc_samples":    20,
            "method":        "Monte Carlo Dropout (variance of segmentation mask)",
        }

    # ── Section 10: Mass Effect ──
    mass_eff = mass_effect if mass_effect else {
        "midline_shift_mm":        None,
        "herniation_risk":         "Not assessed",
        "ventricular_compression": "Not assessed",
        "mass_effect_label":       "Mass effect analysis not performed",
    }

    # ── Section 11: Images ──
    images = {
        'original_slice_b64': original_img_b64,
        'segmentation_overlay_b64': overlay_b64,
    }

    # ── Assemble Full Report ──
    report = {
        'header': header,
        'patient': patient,
        'scan': scan,
        'detection': detection,
        'measurements': meas,
        'radiomics': radiomics_summary,
        'risk_assessment': risk,
        'clinical_impression': impression,
        'images': images,
        'disclaimer': AI_DISCLAIMER,
        'id': report_id,
        'timestamp': timestamp,
        'case_id': patient['case_id'],
        'patient_name': patient['name'],
        'diagnosis': detection['finding'],
        'confidence': confidence,
        'tumor_size': f"{vol_ml:.2f} mL (diameter: {diam_mm:.1f}mm)" if not insufficient_mask_data else "—",
        'tumor_loc': radiomics_summary['anatomical_location'] if not insufficient_mask_data else "—",
        'impression': impression,
        'risk_level': risk['risk_level'] if not insufficient_mask_data else "N/A",
        'risk_score': risk['composite_score'] if not insufficient_mask_data else 0,
        'image_b64': original_img_b64,
        'overlay_b64': overlay_b64,
        'model_version': '2.0',
        'pipeline_stages':     pipeline_stages,
        'insufficient_mask_data': insufficient_mask_data,
        'uncertainty':         uncertainty,
        'mass_effect':         mass_eff,
        'uncertainty_score':   round(float(uncertainty_score), 5) if uncertainty_score is not None else None,
        'midline_shift_mm':    mass_eff.get('midline_shift_mm'),
    }

    return report


def _generate_impression(is_tumor, meas, radiomics_summary, risk, grade_label, uncertainty_score=None, mass_effect=None):
    """Generate a structured clinical impression paragraph."""
    if not is_tumor:
        return (
            "No space-occupying lesions or midline shift identified. "
            "Gray-white matter differentiation is preserved. "
            "Ventricular system and subarachnoid spaces are within normal limits for age. "
            "No evidence of acute intracranial hemorrhage or territorial infarction. "
            "Follow-up recommended as clinically indicated."
        )

    loc = radiomics_summary.get('anatomical_location', 'undetermined region')
    vol = meas.get('volume_ml', 0)
    diam = meas.get('longest_diameter_mm', 0)
    enh = radiomics_summary.get('enhancement_pattern', 'undetermined')
    ring = radiomics_summary.get('ring_enhancement', False)
    edema = radiomics_summary.get('edema_label', 'undetermined')
    shape = radiomics_summary.get('shape_label', 'undetermined')
    risk_level = risk.get('risk_level', 'N/A')
    risk_score = risk.get('composite_score', 0)
    eloquent = radiomics_summary.get('is_eloquent_area', False)
    texture = radiomics_summary.get('texture_label', 'undetermined')

    ring_note = (
        " Ring enhancement pattern is present, raising concern for necrotic core — "
        "a feature often associated with high-grade lesions."
    ) if ring else ""

    eloquent_note = (
        f" The lesion involves an eloquent cortical region — "
        f"surgical approach requires careful planning with neuronavigation."
    ) if eloquent else ""

    grade_note = (
        f" AI grade indicator: {grade_label} (NOTE: WHO grade requires histopathological confirmation)."
    ) if grade_label and grade_label != 'N/A' else ""

    mass_note = ""
    if mass_effect and mass_effect.get('midline_shift_mm', 0) > 0:
        shift = mass_effect['midline_shift_mm']
        direction = mass_effect.get('shift_direction', 'None')
        dir_text = f" to the {direction}" if direction != 'None' else ""
        risk_h = mass_effect.get('herniation_risk', 'Low')
        mass_note = f" Associated midline shift of {shift} mm{dir_text} is noted (herniation risk: {risk_h.lower()})."

    uncertainty_note = ""
    if uncertainty_score is not None:
        uncertainty_note = f" Model uncertainty score is {uncertainty_score:.5f} (MC-Dropout estimation)."

    return (
        f"Analysis reveals a focal intracranial lesion in the {loc}, "
        f"measuring approximately {vol:.1f}mL (longest diameter {diam:.1f}mm). "
        f"Enhancement pattern: {enh}.{ring_note} "
        f"Peritumoral edema: {edema}. "
        f"Shape characteristics: {shape}. "
        f"Texture analysis: {texture}.{mass_note} "
        f"Composite AI risk score: {risk_score}/100 ({risk_level} risk).{eloquent_note}{uncertainty_note} "
        f"Differential diagnosis includes primary glial neoplasm, metastatic lesion, "
        f"or demyelinating process. Correlation with clinical history, contrast MRI, "
        f"MR spectroscopy, and tissue sampling is strongly recommended.{grade_note}"
    )
